import{_ as o,c as a,o as t,aj as s}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: DocumentSnapshotLoadEvent","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotLoadEvent.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotLoadEvent.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotLoadEvent.md"};function r(c,e,d,h,l,i){return t(),a("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentSnapshotLoadEvent</p><h1 id="interface-documentsnapshotloadevent" tabindex="-1">Interface: DocumentSnapshotLoadEvent <a class="header-anchor" href="#interface-documentsnapshotloadevent" aria-label="Permalink to “Interface: DocumentSnapshotLoadEvent”">​</a></h1><p>How a large document&#39;s base snapshot load is going.</p><p>A cold open of a large document streams a base of up to gigabytes before the document is usable, which can take minutes. An app with nothing to show for that is indistinguishable from one that has hung, so the load reports itself: <code>started</code> once the manifest is in hand (which is where <code>totalRows</code> comes from, so a progress bar exists before the first chunk lands), <code>progress</code> per chunk, <code>model</code> as each model becomes queryable, and <code>loaded</code> at the end.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="chunks" tabindex="-1">chunks <a class="header-anchor" href="#chunks" aria-label="Permalink to “chunks”">​</a></h3><blockquote><p><strong>chunks</strong>: <code>number</code></p></blockquote><hr><h3 id="chunksreused" tabindex="-1">chunksReused? <a class="header-anchor" href="#chunksreused" aria-label="Permalink to “chunksReused?”">​</a></h3><blockquote><p><code>optional</code> <strong>chunksReused?</strong>: <code>number</code></p></blockquote><p>Chunks a convergence kept rather than fetched, on the <code>loaded</code> phase of a <code>&quot;converge&quot;</code> load. The saving the whole design exists for.</p><hr><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><hr><h3 id="epoch" tabindex="-1">epoch <a class="header-anchor" href="#epoch" aria-label="Permalink to “epoch”">​</a></h3><blockquote><p><strong>epoch</strong>: <code>number</code></p></blockquote><p>The epoch the snapshot is a base for.</p><hr><h3 id="mode" tabindex="-1">mode? <a class="header-anchor" href="#mode" aria-label="Permalink to “mode?”">​</a></h3><blockquote><p><code>optional</code> <strong>mode?</strong>: <code>&quot;load&quot;</code> | <code>&quot;converge&quot;</code></p></blockquote><p>What this load IS.</p><p><code>&quot;load&quot;</code> installs a base whole — a cold start, or a rebuild. <code>&quot;converge&quot;</code> replaces only the ranges a bulk load touched and keeps the rest, which is why it also reports <a href="#chunksreused">chunksReused</a>.</p><hr><h3 id="model" tabindex="-1">model? <a class="header-anchor" href="#model" aria-label="Permalink to “model?”">​</a></h3><blockquote><p><code>optional</code> <strong>model?</strong>: <code>string</code></p></blockquote><p>The model the event concerns, when it concerns one.</p><hr><h3 id="phase" tabindex="-1">phase <a class="header-anchor" href="#phase" aria-label="Permalink to “phase”">​</a></h3><blockquote><p><strong>phase</strong>: <code>&quot;started&quot;</code> | <code>&quot;progress&quot;</code> | <code>&quot;model&quot;</code> | <code>&quot;loaded&quot;</code></p></blockquote><hr><h3 id="rows" tabindex="-1">rows <a class="header-anchor" href="#rows" aria-label="Permalink to “rows”">​</a></h3><blockquote><p><strong>rows</strong>: <code>number</code></p></blockquote><hr><h3 id="totalchunks" tabindex="-1">totalChunks <a class="header-anchor" href="#totalchunks" aria-label="Permalink to “totalChunks”">​</a></h3><blockquote><p><strong>totalChunks</strong>: <code>number</code></p></blockquote><hr><h3 id="totalrows" tabindex="-1">totalRows <a class="header-anchor" href="#totalrows" aria-label="Permalink to “totalRows”">​</a></h3><blockquote><p><strong>totalRows</strong>: <code>number</code></p></blockquote>',41)])])}const b=o(n,[["render",r]]);export{p as __pageData,b as default};
